:root {
    /* Brand Colors */
    --color-primary: #2D6A4F;
    --color-primary-hover: #1B4332;
    --color-accent: #F4A261;
    --color-accent-hover: #E76F51;
    --color-bg: #FEFAE0;
    --color-bg-alt: #FFFcf0;

    /* Neutral Colors */
    --color-text: #1E293B;
    --color-text-muted: #475569;
    --color-border: #E2E8F0;
    --color-white: #FFFFFF;

    /* Typography */
    --font-heading: 'Nunito', sans-serif;
    --font-body: 'Inter', sans-serif;

    /* Spacing & Sizes */
    --container-max: 1152px;
    --radius-sm: 8px;
    --radius-md: 16px;
    --radius-lg: 24px;
    --radius-full: 9999px;

    /* Shadows */
    --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
    --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
    --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
    --shadow-hover: 0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 10px 10px -5px rgba(0, 0, 0, 0.04);

    /* Transitions */
    --transition-fast: 150ms ease;
    --transition-normal: 300ms ease;
}

/* Reset & Base */
*, *::before, *::after {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

html {
    scroll-behavior: smooth;
}

body {
    font-family: var(--font-body);
    color: var(--color-text);
    background-color: var(--color-bg);
    line-height: 1.6;
    -webkit-font-smoothing: antialiased;
}

img {
    max-width: 100%;
    height: auto;
    display: block;
}

a {
    color: inherit;
    text-decoration: none;
    transition: color var(--transition-fast);
}

ul {
    list-style: none;
}

button {
    cursor: pointer;
    font-family: inherit;
    border: none;
    background: none;
}

.container {
    width: 100%;
    max-width: var(--container-max);
    margin: 0 auto;
    padding: 0 1.5rem;
}

.section-padding {
    padding: 5rem 0;
}

.text-center {
    text-align: center;
}

.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border-width: 0;
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
    font-family: var(--font-heading);
    line-height: 1.2;
    font-weight: 700;
    color: var(--color-primary);
}

.section-title {
    font-size: 2.25rem;
    margin-bottom: 1rem;
}

.section-subtitle {
    font-size: 1.125rem;
    color: var(--color-text-muted);
    max-width: 600px;
    margin: 0 auto 3rem;
}

/* Buttons */
.btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 0.75rem 1.5rem;
    font-weight: 600;
    border-radius: var(--radius-full);
    transition: all var(--transition-fast);
    text-align: center;
    min-height: 44px; /* Touch target size */
}

.btn-primary {
    background-color: var(--color-primary);
    color: var(--color-white);
}

.btn-primary:hover, .btn-primary:focus-visible {
    background-color: var(--color-primary-hover);
    transform: translateY(-2px);
    box-shadow: var(--shadow-md);
    outline: 2px solid var(--color-primary);
    outline-offset: 2px;
}

.btn-secondary {
    background-color: var(--color-white);
    color: var(--color-primary);
    border: 2px solid var(--color-primary);
}

.btn-secondary:hover, .btn-secondary:focus-visible {
    background-color: var(--color-bg);
    transform: translateY(-2px);
    box-shadow: var(--shadow-md);
}

/* Header */
.site-header {
    background-color: var(--color-white);
    box-shadow: var(--shadow-sm);
    position: sticky;
    top: 0;
    z-index: 100;
}

.header-inner {
    display: flex;
    align-items: center;
    justify-content: space-between;
    height: 72px;
}

.brand-logo {
    font-family: var(--font-heading);
    font-size: 1.5rem;
    font-weight: 800;
    color: var(--color-primary);
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.logo-icon {
    font-size: 1.75rem;
}

.main-nav .nav-list {
    display: flex;
    gap: 2rem;
}

.nav-link {
    font-weight: 500;
    color: var(--color-text-muted);
    padding: 0.5rem 0;
    position: relative;
}

.nav-link::after {
    content: '';
    position: absolute;
    bottom: 0;
    left: 0;
    width: 0;
    height: 2px;
    background-color: var(--color-primary);
    transition: width var(--transition-fast);
}

.nav-link:hover, .nav-link:focus-visible {
    color: var(--color-primary);
}

.nav-link:hover::after, .nav-link:focus-visible::after {
    width: 100%;
}

.mobile-menu-toggle {
    display: none;
    color: var(--color-primary);
    padding: 0.5rem;
}

/* Hero Section */
.hero {
    padding: 6rem 0;
    background-color: var(--color-bg);
    overflow: hidden;
}

.hero-inner {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 4rem;
    align-items: center;
}

.hero-title {
    font-size: 3.5rem;
    margin-bottom: 1.5rem;
    color: var(--color-primary);
}

.hero-subtitle {
    font-size: 1.25rem;
    color: var(--color-text-muted);
    margin-bottom: 2.5rem;
    max-width: 500px;
}

.hero-actions {
    display: flex;
    gap: 1rem;
    flex-wrap: wrap;
}

.hero-visual {
    position: relative;
    height: 400px;
    display: flex;
    justify-content: center;
    align-items: center;
}

.visual-card {
    position: absolute;
    background: var(--color-white);
    padding: 1.5rem 2rem;
    border-radius: var(--radius-lg);
    box-shadow: var(--shadow-lg);
    font-family: var(--font-heading);
    font-weight: 700;
    font-size: 1.5rem;
    color: var(--color-primary);
    display: flex;
    align-items: center;
    gap: 0.5rem;
    animation: float 6s ease-in-out infinite;
}

.visual-1 {
    top: 10%;
    left: 10%;
    transform: rotate(-5deg);
    animation-delay: 0s;
}

.visual-2 {
    top: 40%;
    right: 5%;
    transform: rotate(5deg);
    animation-delay: -2s;
}

.visual-3 {
    bottom: 15%;
    left: 20%;
    transform: rotate(-2deg);
    animation-delay: -4s;
}

@keyframes float {
    0%, 100% { transform: translateY(0) rotate(var(--rot, 0deg)); }
    50% { transform: translateY(-15px) rotate(var(--rot, 0deg)); }
}

.visual-1 { --rot: -5deg; }
.visual-2 { --rot: 5deg; }
.visual-3 { --rot: -2deg; }

/* Featured Products (Carousel) */
.featured-products {
    background-color: var(--color-white);
}

.section-header-row {
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    margin-bottom: 2.5rem;
}

.section-header-row .section-title {
    margin-bottom: 0;
}

.carousel-controls {
    display: flex;
    gap: 0.5rem;
}

.carousel-btn {
    width: 48px;
    height: 48px;
    border-radius: 50%;
    background-color: var(--color-bg);
    color: var(--color-primary);
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all var(--transition-fast);
}

.carousel-btn:hover:not(:disabled) {
    background-color: var(--color-primary);
    color: var(--color-white);
}

.carousel-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

.carousel-viewport {
    overflow: hidden;
    margin: 0 -1.5rem;
    padding: 0 1.5rem;
}

.carousel-track {
    display: flex;
    gap: 1.5rem;
    transition: transform var(--transition-normal);
    will-change: transform;
}

.product-card {
    flex: 0 0 280px;
    background: var(--color-white);
    border-radius: var(--radius-md);
    overflow: hidden;
    box-shadow: var(--shadow-md);
    border: 1px solid var(--color-border);
    transition: transform var(--transition-fast), box-shadow var(--transition-fast);
    display: flex;
    flex-direction: column;
}

.product-card:hover {
    transform: translateY(-4px);
    box-shadow: var(--shadow-hover);
}

.product-image {
    height: 200px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 5rem;
}

.product-info {
    padding: 1.5rem;
    display: flex;
    flex-direction: column;
    flex-grow: 1;
}

.product-name {
    font-size: 1.25rem;
    margin-bottom: 0.5rem;
}

.product-desc {
    color: var(--color-text-muted);
    font-size: 0.9375rem;
    margin-bottom: 1rem;
    flex-grow: 1;
}

.product-price {
    font-weight: 700;
    font-size: 1.25rem;
    color: var(--color-accent);
}

/* Seasonal Picks */
.background-accent {
    background-color: var(--color-bg-alt);
    border-top: 1px solid var(--color-border);
    border-bottom: 1px solid var(--color-border);
}

.seasonal-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
    gap: 2rem;
}

.seasonal-card {
    background: var(--color-white);
    border-radius: var(--radius-lg);
    padding: 2rem;
    text-align: center;
    box-shadow: var(--shadow-sm);
    transition: transform var(--transition-fast);
}

.seasonal-card:hover {
    transform: translateY(-5px);
    box-shadow: var(--shadow-md);
}

.seasonal-emoji {
    font-size: 4rem;
    margin-bottom: 1rem;
}

.seasonal-name {
    font-size: 1.25rem;
    margin-bottom: 0.5rem;
}

.seasonal-desc {
    font-size: 0.9375rem;
    color: var(--color-text-muted);
    margin-bottom: 1rem;
}

/* Categories */
.category-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 1.5rem;
    margin-top: 3rem;
}

.category-card {
    position: relative;
    border-radius: var(--radius-md);
    overflow: hidden;
    aspect-ratio: 1;
    display: block;
    box-shadow: var(--shadow-sm);
}

.cat-visual {
    width: 100%;
    height: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 5rem;
    transition: transform var(--transition-normal);
}

.cat-overlay {
    position: absolute;
    inset: 0;
    background: rgba(45, 106, 79, 0.9);
    color: var(--color-white);
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 1.5rem;
    text-align: center;
    opacity: 0;
    transition: opacity var(--transition-normal);
}

.category-card:hover .cat-visual, .category-card:focus-visible .cat-visual {
    transform: scale(1.1);
}

.category-card:hover .cat-overlay, .category-card:focus-visible .cat-overlay {
    opacity: 1;
}

.cat-name {
    color: var(--color-white);
    font-size: 1.5rem;
    margin-bottom: 0.5rem;
    transform: translateY(10px);
    transition: transform var(--transition-normal);
}

.cat-desc {
    font-size: 0.9375rem;
    transform: translateY(10px);
    transition: transform var(--transition-normal);
}

.category-card:hover .cat-name, .category-card:hover .cat-desc,
.category-card:focus-visible .cat-name, .category-card:focus-visible .cat-desc {
    transform: translateY(0);
}

/* Brand Highlights (Stats) */
.brand-highlights {
    background-color: var(--color-primary);
    color: var(--color-white);
    padding: 4rem 0;
}

.stats-list {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 2rem;
    text-align: center;
}

.stat-value {
    display: block;
    font-family: var(--font-heading);
    font-size: 3rem;
    font-weight: 800;
    color: var(--color-accent);
    line-height: 1;
    margin-bottom: 0.5rem;
}

.stat-label {
    font-size: 1.125rem;
    font-weight: 500;
}

/* Store Locator */
.store-locator {
    background-color: var(--color-white);
}

.locator-inner {
    max-width: 800px;
    text-align: center;
}

.input-group {
    display: flex;
    max-width: 500px;
    margin: 0 auto;
    gap: 0.5rem;
}

.input-group input {
    flex-grow: 1;
    padding: 0.75rem 1.5rem;
    border: 2px solid var(--color-border);
    border-radius: var(--radius-full);
    font-size: 1rem;
    font-family: inherit;
    transition: border-color var(--transition-fast);
    min-height: 44px;
}

.input-group input:focus {
    outline: none;
    border-color: var(--color-primary);
}

.store-results {
    margin-top: 3rem;
    text-align: left;
}

.store-result-card {
    background: var(--color-bg-alt);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-md);
    padding: 1.5rem;
    margin-bottom: 1rem;
    display: flex;
    justify-content: space-between;
    align-items: center;
    animation: fadeIn 0.3s ease-out;
}

@keyframes fadeIn {
    from { opacity: 0; transform: translateY(10px); }
    to { opacity: 1; transform: translateY(0); }
}

.store-result-info h3 {
    font-size: 1.25rem;
    margin-bottom: 0.25rem;
}

.store-result-info p {
    color: var(--color-text-muted);
    font-size: 0.9375rem;
}

.store-result-meta {
    text-align: right;
}

.store-distance {
    font-weight: 600;
    color: var(--color-primary);
    font-size: 1.125rem;
    display: block;
}

/* Newsletter */
.newsletter-box {
    background-color: var(--color-accent);
    border-radius: var(--radius-lg);
    padding: 4rem 2rem;
    text-align: center;
    color: var(--color-white);
}

.newsletter-box .section-title, .newsletter-box .section-subtitle {
    color: var(--color-white);
}

.newsletter-form .btn-primary {
    background-color: var(--color-text);
}

.newsletter-form .btn-primary:hover {
    background-color: var(--color-primary-hover);
}

.newsletter-message {
    margin-top: 1rem;
    font-weight: 500;
}

/* Footer */
.site-footer {
    background-color: var(--color-text);
    color: var(--color-white);
    padding: 5rem 0 2rem;
}

.footer-grid {
    display: grid;
    grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
    gap: 3rem;
    margin-bottom: 4rem;
}

.footer-brand {
    font-family: var(--font-heading);
    font-size: 1.5rem;
    font-weight: 800;
    color: var(--color-white);
    display: flex;
    align-items: center;
    gap: 0.5rem;
    margin-bottom: 1rem;
}

.brand-col .tagline {
    color: #94A3B8;
}

.footer-heading {
    color: var(--color-white);
    font-size: 1.125rem;
    margin-bottom: 1.5rem;
}

.footer-links li {
    margin-bottom: 0.75rem;
}

.footer-links a {
    color: #94A3B8;
}

.footer-links a:hover, .footer-links a:focus-visible {
    color: var(--color-accent);
}

.footer-bottom {
    text-align: center;
    padding-top: 2rem;
    border-top: 1px solid #334155;
    color: #94A3B8;
    font-size: 0.875rem;
}

/* Responsive */
@media (max-width: 1024px) {
    .stats-list {
        grid-template-columns: repeat(2, 1fr);
    }

    .footer-grid {
        grid-template-columns: 1fr 1fr;
    }

    .brand-col {
        grid-column: 1 / -1;
    }
}

@media (max-width: 768px) {
    .hero-inner {
        grid-template-columns: 1fr;
        text-align: center;
    }

    .hero-title {
        font-size: 2.5rem;
    }

    .hero-actions {
        justify-content: center;
    }

    .hero-visual {
        height: 300px;
    }

    .main-nav {
        display: none;
    }

    .mobile-menu-toggle {
        display: block;
    }

    .input-group {
        flex-direction: column;
    }

    .input-group .btn {
        width: 100%;
    }

    .store-result-card {
        flex-direction: column;
        align-items: flex-start;
        gap: 1rem;
    }

    .store-result-meta {
        text-align: left;
    }
}

@media (max-width: 480px) {
    .stats-list {
        grid-template-columns: 1fr;
    }

    .footer-grid {
        grid-template-columns: 1fr;
    }
}

document.addEventListener('DOMContentLoaded', () => {

    // --- Mobile Menu Toggle (Optional Enhancement) ---
    const mobileMenuToggle = document.querySelector('.mobile-menu-toggle');
    const mainNav = document.querySelector('.main-nav');

    if (mobileMenuToggle && mainNav) {
        mobileMenuToggle.addEventListener('click', () => {
            const isExpanded = mobileMenuToggle.getAttribute('aria-expanded') === 'true';
            mobileMenuToggle.setAttribute('aria-expanded', !isExpanded);
            mainNav.style.display = isExpanded ? 'none' : 'block';
        });
    }

    // --- Product Carousel ---
    const track = document.querySelector('.carousel-track');
    const prevBtn = document.querySelector('.prev-btn');
    const nextBtn = document.querySelector('.next-btn');

    if (track && prevBtn && nextBtn) {
        // Using scrollLeft instead of transform for a simpler, native-feeling scroll
        // Wait, track is currently set up with 'transition: transform' in CSS. 
        // We'll update the JS to use scroll container if we change CSS, but let's stick to CSS transforms for smooth sliding or just change container to overflow: auto.
        // Actually, using a simple index-based transform is easy:
        let currentScroll = 0;
        const cardWidth = 280 + 24; // Card width + gap (1.5rem = 24px)
        const visibleWidth = document.querySelector('.carousel-viewport').offsetWidth;
        const totalWidth = track.scrollWidth;

        const updateButtons = () => {
            prevBtn.disabled = currentScroll <= 0;
            // Allow scrolling until the last item is fully visible
            nextBtn.disabled = currentScroll >= (totalWidth - visibleWidth);
        };

        nextBtn.addEventListener('click', () => {
            currentScroll += cardWidth;
            if (currentScroll > totalWidth - visibleWidth) {
                currentScroll = totalWidth - visibleWidth;
            }
            track.style.transform = `translateX(-${currentScroll}px)`;
            updateButtons();
        });

        prevBtn.addEventListener('click', () => {
            currentScroll -= cardWidth;
            if (currentScroll < 0) {
                currentScroll = 0;
            }
            track.style.transform = `translateX(-${currentScroll}px)`;
            updateButtons();
        });

        // Handle resize
        window.addEventListener('resize', () => {
            currentScroll = 0;
            track.style.transform = `translateX(0px)`;
            updateButtons();
        });

        // Initialize
        updateButtons();
    }

    // --- Store Locator ---
    const storeForm = document.getElementById('store-search-form');
    const storeResults = document.getElementById('store-results');

    const storesData = [
        {
            name: 'Fresh Pantry — Lincoln Park',
            address: '2140 N. Halsted St, Chicago, IL 60614',
            hours: '8am – 9pm Daily',
            distance: '0.8 mi'
        },
        {
            name: 'Fresh Pantry — Wicker Park',
            address: '1840 W. North Ave, Chicago, IL 60622',
            hours: '8am – 9pm Daily',
            distance: '1.4 mi'
        },
        {
            name: 'Fresh Pantry — Lakeview',
            address: '3745 N. Lincoln Ave, Chicago, IL 60613',
            hours: '8am – 9pm Daily',
            distance: '2.1 mi'
        }
    ];

    if (storeForm && storeResults) {
        storeForm.addEventListener('submit', (e) => {
            e.preventDefault();
            const zipcodeInput = document.getElementById('zipcode');
            const zip = zipcodeInput.value.trim();

            if (zip) {
                // Simulate network delay
                storeResults.innerHTML = '<p>Searching for nearby stores...</p>';

                setTimeout(() => {
                    storeResults.innerHTML = ''; // clear loading

                    storesData.forEach((store, index) => {
                        const delay = index * 100; // stagger animation
                        const card = document.createElement('div');
                        card.className = 'store-result-card';
                        card.style.animationDelay = `${delay}ms`;

                        card.innerHTML = `
                            <div class="store-result-info">
                                <h3>${store.name}</h3>
                                <p>${store.address}</p>
                                <p><strong>Hours:</strong> ${store.hours}</p>
                            </div>
                            <div class="store-result-meta">
                                <span class="store-distance">${store.distance}</span>
                            </div>
                        `;
                        storeResults.appendChild(card);
                    });
                }, 500);
            }
        });
    }

    // --- Newsletter Signup ---
    const newsletterForm = document.getElementById('newsletter-form');
    const newsletterMessage = document.getElementById('newsletter-message');

    if (newsletterForm && newsletterMessage) {
        newsletterForm.addEventListener('submit', (e) => {
            e.preventDefault();
            const emailInput = document.getElementById('email');

            if (emailInput.value.trim() !== '') {
                // Hide input, show success message
                newsletterMessage.textContent = 'Thanks for subscribing! Check your inbox for a welcome treat.';
                newsletterMessage.hidden = false;

                // Clear input
                emailInput.value = '';
            }
        });
    }
});

